 90	        const std::map<std::string, E::NystromLandmarkSource> sources{{"points", E::NystromLandmarkSource::Points},
 91	                                                                      {"box", E::NystromLandmarkSource::BoundingBox}};
 92	        const std::map<std::string, E::NystromLandmarkSchedule> schedules{{"mixed", E::NystromLandmarkSchedule::Mixed},
 93	                                                                          {"fixed", E::NystromLandmarkSchedule::Fixed},
 94	                                                                          {"resampled", E::NystromLandmarkSchedule::Resampled}};
 95	        const std::map<std::string, E::NystromBoxPattern> patterns{{"random", E::NystromBoxPattern::Random},
 96	                                                                   {"halton", E::NystromBoxPattern::Halton}};
 97	        if (!sources.contains(source) || !schedules.contains(schedule) || !patterns.contains(pattern)) return false;
 98	        params.EStep = CPD::EStepPolicy::Nystrom;
