1339	        void BuildLandmarks(const PointSet target, const PointSet moved, const std::size_t landmarks, const double sigma2,
1340	                            const Settings& settings)
1341	        {
1342	            const std::size_t n = target.Size(), m = moved.Size();
1343	            const auto schedule = settings.NystromSchedule;
1344	            // Another source starts the variant's draws afresh (fixed orders and boxes belong to it).
1345	            if (m != NystromSourceSize)
1346	            {
1347	                ResetLandmarkVariant();
1348	                NystromSourceSize = m;
1349	            }
1350	            LandmarkX.clear(); LandmarkY.clear(); LandmarkZ.clear();
1351	            if (settings.NystromSource == NystromLandmarkSource::BoundingBox)
1352	            {
1353	                if (!BoxesFrozen)
1354	                {
1355	                    const double pad = std::sqrt(sigma2);
1356	                    Boxes = {PaddedBox(target, pad), PaddedBox(moved, pad)};
1357	                    BoxesFrozen = schedule == NystromLandmarkSchedule::Fixed;
1358	                }
1359	                const std::uint64_t seed =
1360	                    settings.NystromSampling.Seed + (schedule == NystromLandmarkSchedule::Resampled ? NystromDraw : 0u);
1361	                UnionBoxPoints(Boxes[0], Boxes[1], landmarks, settings.NystromPattern, seed, LandmarkX, LandmarkY, LandmarkZ);
1362	                return;
1363	            }
1364	            const std::size_t half = std::max<std::size_t>(1u, landmarks / 2u);
1365	            const auto append = [&](const PointSet set, const std::span<const std::uint32_t> order) {
1366	                for (std::size_t k = 0; k < std::min(half, order.size()); ++k)
1367	                {
1368	                    const std::size_t i = order[k];
1369	                    LandmarkX.push_back(set.X[i]); LandmarkY.push_back(set.Y[i]); LandmarkZ.push_back(set.Z[i]);
1370	                }
1371	            };
1372	            if (schedule == NystromLandmarkSchedule::Resampled)
1373	            {
1374	                // Every seed of the sampling methods moves with the draw, and so does the start point.
1375	                const auto draw = [&](const PointSet set) {
1376	                    PointSampling::Params params = settings.NystromSampling;
1377	                    const auto shift = std::uint32_t(NystromDraw);
1378	                    params.Seed += NystromDraw;
1379	                    params.FirstIndex = std::uint32_t((std::uint64_t(params.FirstIndex) + NystromDraw) % set.Size());
