1419	        bool NystromRows(const PointSet& moved, const double sigma2, const double logC, const std::size_t landmarks,
1420	                         const double errorLimit, const Settings& settings, Sums& out,
1421	                         const std::uint32_t threads, double& sampledError, std::uint64_t& evaluations)
1422	        {
1423	            const PointSet target = Target();
1424	            const std::size_t n = target.Size(), m = moved.Size();
1425	            BuildLandmarks(target, moved, landmarks, sigma2, settings);
1426	            const std::size_t l = LandmarkX.size();
1427	            if (l == 0u) return false;
1428	            LandmarkZero.assign(l, 0.0);
1429	            const double inverseTwoSigma2 = 0.5 / sigma2;
1430	            const auto kernelRow = [&](const double x, const double y, const double z, double* row)
1431	            {
1432	                (void)DenseRowTerms(LandmarkX.data(), LandmarkY.data(), LandmarkZ.data(), LandmarkZero.data(), l, x, y, z,
1433	                                    0.0, inverseTwoSigma2, row);
1434	            };
1435	            Eigen::MatrixXd gram{Eigen::Index(l), Eigen::Index(l)};
1436	            for (std::size_t a = 0; a < l; ++a)
1437	                kernelRow(LandmarkX[a], LandmarkY[a], LandmarkZ[a], gram.col(Eigen::Index(a)).data());
1438	            const Eigen::SelfAdjointEigenSolver<Eigen::MatrixXd> eigen(gram);
1439	            if (eigen.info() != Eigen::Success) return false;
1440	            const double top = eigen.eigenvalues().maxCoeff();
1441	            if (!(top > 0.0)) return false;
1442	            // Pseudo-inverse on the numerically positive spectrum.
1443	            constexpr double kCutoff = 1.0e-10;
1444	            const Eigen::VectorXd inverse =
1445	                eigen.eigenvalues().unaryExpr([&](const double v) { return v > kCutoff * top ? 1.0 / v : 0.0; });
1446	            const Eigen::MatrixXd pseudoInverse = eigen.eigenvectors() * inverse.asDiagonal() * eigen.eigenvectors().transpose();
1447	
1448	            constexpr std::size_t kGrain = 1024;
1449	            // Pass 1 (sources): a = sum_m w_m k(Z, y_m).
1450	            const std::size_t sourceChunks = (m + kGrain - 1) / kGrain, targetChunks = (n + kGrain - 1) / kGrain;
1451	            std::vector<double> partial(std::max(sourceChunks, targetChunks) * 4u * l, 0.0);
1452	            ParallelFor(m, kGrain, threads, [&](const std::size_t begin, const std::size_t end)
1453	            {
1454	                std::vector<double> row(l);
1455	                double* sum = partial.data() + (begin / kGrain) * l;
1456	                for (std::size_t i = begin; i < end; ++i)
1457	                {
1458	                    kernelRow(moved.X[i], moved.Y[i], moved.Z[i], row.data());
1459	                    const double weight = std::exp(LogWeight[i]);
1460	                    for (std::size_t k = 0; k < l; ++k) sum[k] += weight * row[k];
1461	                }
1462	            });
1463	            Eigen::VectorXd a = Eigen::VectorXd::Zero(Eigen::Index(l));
1464	            for (std::size_t c = 0; c < sourceChunks; ++c)
1465	                for (std::size_t k = 0; k < l; ++k) a[Eigen::Index(k)] += partial[c * l + k];
1466	            const Eigen::VectorXd g = pseudoInverse * a;
1467	
1468	            // Pass 2 (targets): shifted sums S_n = k(x_n, Z) g, denominators, Pt1, and
1469	            // h = sum_n d_n k(Z, x_n) (1, x_n) with d_n = e^{shift} / den_n.
1470	            std::fill(partial.begin(), partial.end(), 0.0);
1471	            std::vector<double> scale(n, 0.0);
1472	            std::atomic<bool> valid{true};
1473	            ParallelFor(n, kGrain, threads, [&](const std::size_t begin, const std::size_t end)
1474	            {
1475	                std::vector<double> row(l);
1476	                double* sum = partial.data() + (begin / kGrain) * 4u * l;
1477	                for (std::size_t j = begin; j < end; ++j)
1478	                {
1479	                    kernelRow(target.X[j], target.Y[j], target.Z[j], row.data());
1480	                    double shifted = 0.0;
1481	                    for (std::size_t k = 0; k < l; ++k) shifted += row[k] * g[Eigen::Index(k)];
1482	                    if (!(shifted > 0.0) || !std::isfinite(shifted)) { valid = false; return; }
1483	                    LogDenominator[j] = LogSumWithOutlier(LogWeightShift, shifted, logC);
1484	                    const double d = std::exp(LogWeightShift - LogDenominator[j]);
1485	                    scale[j] = d;
1486	                    out.Pt1[j] = shifted * d;
1487	                    RowEvaluations[j] = l;
1488	                    for (std::size_t k = 0; k < l; ++k)
1489	                    {
1490	                        const double t = d * row[k];
1491	                        sum[k] += t;
1492	                        sum[l + k] += t * target.X[j];
1493	                        sum[2u * l + k] += t * target.Y[j];
1494	                        sum[3u * l + k] += t * target.Z[j];
1495	                    }
1496	                }
1497	            });
1498	            if (!valid) { std::fprintf(stderr, "NYSTROM_DIAG invalid_target %llu %zu\n", (unsigned long long)NystromDraw, l); return false; }
1499	            Eigen::MatrixXd h = Eigen::MatrixXd::Zero(Eigen::Index(l), 4);
1500	            for (std::size_t c = 0; c < targetChunks; ++c)
1501	                for (Eigen::Index column = 0; column < 4; ++column)
1502	                    for (std::size_t k = 0; k < l; ++k)
1503	                        h(Eigen::Index(k), column) += partial[(c * 4u + std::size_t(column)) * l + k];
1504	            const Eigen::MatrixXd q = pseudoInverse * h;
1505	
1506	            // Pass 3 (sources): P1 and PX.
1507	            ParallelFor(m, kGrain, threads, [&](const std::size_t begin, const std::size_t end)
1508	            {
1509	                std::vector<double> row(l);
1510	                for (std::size_t i = begin; i < end; ++i)
1511	                {
1512	                    kernelRow(moved.X[i], moved.Y[i], moved.Z[i], row.data());
1513	                    double v[4]{0.0, 0.0, 0.0, 0.0};
1514	                    for (std::size_t k = 0; k < l; ++k)
1515	                        for (Eigen::Index column = 0; column < 4; ++column) v[column] += row[k] * q(Eigen::Index(k), column);
1516	                    const double weight = std::exp(LogWeight[i]);
1517	                    if (!(v[0] >= 0.0) || !std::isfinite(v[1] + v[2] + v[3])) { valid = false; return; }
1518	                    out.P1[i] = weight * v[0]; out.PXx[i] = weight * v[1]; out.PXy[i] = weight * v[2]; out.PXz[i] = weight * v[3];
1519	                }
1520	            });
1521	            if (!valid) { std::fprintf(stderr, "NYSTROM_DIAG invalid_source %llu %zu\n", (unsigned long long)NystromDraw, l); return false; }
1522	
1523	            // A-posteriori check on exact rows spread over both sets.
1524	            const std::size_t samples = 32u;
1525	            const std::size_t targetSamples = std::min(samples, n), sourceSamples = std::min(samples, m);
1526	            std::vector<double> errors(targetSamples + sourceSamples, 0.0);
1527	            ParallelFor(targetSamples + sourceSamples, 1, threads, [&](const std::size_t begin, const std::size_t end)
1528	            {
1529	                std::vector<double> buffer(std::max(n, m));
1530	                for (std::size_t r = begin; r < end; ++r)
1531	                {
1532	                    if (r < targetSamples)
1533	                    {
1534	                        const std::size_t j = r * n / targetSamples;
1535	                        const double exact = DenseRowTerms(moved.X.data(), moved.Y.data(), moved.Z.data(), LogWeight.data(),
1536	                                                           m, target.X[j], target.Y[j], target.Z[j], 0.0, inverseTwoSigma2,
1537	                                                           buffer.data());
1538	                        const double logExact = LogSumWithOutlier(LogWeightShift, exact, logC);
1539	                        errors[r] = std::abs(std::expm1(LogDenominator[j] - logExact));
1540	                    }
1541	                    else
1542	                    {
1543	                        const std::size_t i = (r - targetSamples) * m / sourceSamples;
1544	                        SourceRowTerms(target.X.data(), target.Y.data(), target.Z.data(), LogDenominator.data(), n,
1545	                                       moved.X[i], moved.Y[i], moved.Z[i], inverseTwoSigma2, LogWeight[i] + LogWeightShift,
1546	                                       buffer.data());
1547	                        double exact = 0.0;
1548	                        for (std::size_t j = 0; j < n; ++j) exact += buffer[j];
1549	                        errors[r] = exact > 0.0 ? std::abs(out.P1[i] - exact) / exact
1550	                                                : (out.P1[i] > 0.0 ? std::numeric_limits<double>::infinity() : 0.0);
1551	                    }
1552	                }
1553	            });
1554	            sampledError = 0.0;
1555	            for (const double e : errors) sampledError = std::isnan(e) ? std::numeric_limits<double>::infinity()
1556	                                                                       : std::max(sampledError, e);
1557	            evaluations = std::uint64_t(l) * (2u * std::uint64_t(m) + std::uint64_t(l)) +
1558	                          std::uint64_t(targetSamples) * m + std::uint64_t(sourceSamples) * n;
1559	            return sampledError <= errorLimit;
1560	        }

