    23	    inline glm::vec3 SurfacePoint(double u, double v)
    24	    {
    25	        // Bumpy ellipsoid: a closed 2-D surface, like a scanned object.
    26	        const double r = 1.0 + 0.15 * std::sin(5.0 * u) * std::cos(4.0 * v);
    27	        return glm::vec3(float(r * std::cos(u) * std::sin(v)), float(0.8 * r * std::sin(u) * std::sin(v)),
    28	                         float(0.6 * r * std::cos(v)));
    29	    }
