    31	    inline std::vector<glm::vec3> Surface(std::size_t count, std::uint32_t seed)
    32	    {
    33	        std::mt19937 random(seed);
    34	        std::uniform_real_distribution<double> uniform(0.0, 1.0);
    35	        std::vector<glm::vec3> points(count);
    36	        for (auto& p : points)
    37	            p = SurfacePoint(2.0 * std::numbers::pi * uniform(random), std::acos(1.0 - 2.0 * uniform(random)));
    38	        return points;
    39	    }
