    41	    inline Fixture RigidFixture(std::size_t count)
    42	    {
    43	        Fixture f;
    44	        f.Source = Surface(count, 1234u + std::uint32_t(count));
    45	        const glm::dmat3 rotation(glm::rotate(glm::dmat4(1.0), 0.35, glm::normalize(glm::dvec3(1.0, 2.0, 0.5))));
    46	        const glm::dvec3 translation{0.3, -0.2, 0.1};
    47	        std::mt19937 random(99u + std::uint32_t(count));
    48	        std::normal_distribution<double> noise(0.0, 0.004);
    49	        std::uniform_real_distribution<double> clutter(-1.5, 1.5);
    50	        for (std::size_t i = 0; i < count; ++i)
    51	        {
    52	            const glm::dvec3 q = rotation * glm::dvec3(f.Source[i]) + translation;
    53	            f.Truth.push_back(glm::vec3(q));
    54	            f.Target.push_back(i % 20 == 0 ? glm::vec3(float(clutter(random)), float(clutter(random)), float(clutter(random)))
    55	                                            : glm::vec3(q + glm::dvec3(noise(random), noise(random), noise(random))));
    56	        }
    57	        return f;
    58	    }
